/**
 * 稼働管理システム（秘書×クライアント多対多対応）
 * Spreadsheet: 稼働管理表_3Link
 */

const SHEET = {
  master : '担当マスター',
  record : '稼働記録',
  secSum : '秘書別サマリー',
  cliSum : 'クライアント別サマリー',
};

const COL = {
  // 担当マスター
  masterSecName  : 1, // A
  masterEmail    : 2, // B
  masterClient   : 3, // C
  // 稼働記録
  recDate        : 1, // A
  recSecName     : 2, // B
  recClient      : 3, // C
  recStart       : 4, // D
  recEnd         : 5, // E
  recHours       : 6, // F
  recMemo        : 7, // G
  recNote        : 8, // H
  recFlag        : 9, // I
};

const HEADER_ROW = 3; // データヘッダー行（1始まり）
const DATA_START  = 4; // データ開始行（1始まり）

// ============================================================
// Web App エントリーポイント
// ============================================================

function doGet() {
  return HtmlService.createHtmlOutputFromFile('フォーム')
    .setTitle('稼働管理')
    .setXFrameOptionsMode(HtmlService.XFrameOptionsMode.ALLOWALL);
}

// ============================================================
// クライアント向けAPI（google.script.run から呼び出し）
// ============================================================

/** ログインユーザーの担当クライアント一覧を返す */
function getMyClients() {
  const email = Session.getActiveUser().getEmail();
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheet = ss.getSheetByName(SHEET.master);
  const rows = sheet.getDataRange().getValues();

  const clients = [];
  for (let i = HEADER_ROW; i < rows.length; i++) {
    const rowEmail  = String(rows[i][COL.masterEmail - 1]).trim();
    const rowClient = String(rows[i][COL.masterClient - 1]).trim();
    const secName   = String(rows[i][COL.masterSecName - 1]).trim();
    if (rowEmail === email && rowClient !== '') {
      clients.push({ name: rowClient, secName: secName });
    }
  }
  return { email: email, clients: clients };
}

/** 現在稼働中のレコードを返す（終了時刻が空のもの） */
function getCurrentWorking() {
  const email = Session.getActiveUser().getEmail();
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheet = ss.getSheetByName(SHEET.record);

  // マスターでメール→秘書名を取得
  const secName = _getSecName(email);
  if (!secName) return null;

  const lastRow = sheet.getLastRow();
  if (lastRow < DATA_START) return null;

  const data = sheet.getRange(DATA_START, 1, lastRow - DATA_START + 1, COL.recNote).getValues();
  for (let i = data.length - 1; i >= 0; i--) {
    const rowSec   = String(data[i][COL.recSecName - 1]).trim();
    const rowStart = data[i][COL.recStart - 1];
    const rowEnd   = data[i][COL.recEnd - 1];
    if (rowSec === secName && rowStart !== '' && rowEnd === '') {
      return {
        client   : String(data[i][COL.recClient - 1]).trim(),
        startTime: _formatTime(rowStart),
        rowIndex : DATA_START + i,
      };
    }
  }
  return null;
}

/** 稼働開始 */
function startWork(clientName, memo) {
  const email = Session.getActiveUser().getEmail();
  const secName = _getSecName(email);
  if (!secName) return { ok: false, msg: '担当マスターにメールアドレスが登録されていません。' };

  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheet = ss.getSheetByName(SHEET.record);
  const now = new Date();
  const jst = _toJST(now);

  // 既存稼働中があれば自動終了
  const current = getCurrentWorking();
  if (current) {
    _setEndTime(sheet, current.rowIndex, jst);
  }

  // 新レコード追加
  const dateStr  = Utilities.formatDate(jst, 'Asia/Tokyo', 'yyyy/MM/dd');
  const timeStr  = Utilities.formatDate(jst, 'Asia/Tokyo', 'HH:mm');
  const newRow   = sheet.getLastRow() + 1;

  sheet.getRange(newRow, COL.recDate   ).setValue(dateStr);
  sheet.getRange(newRow, COL.recSecName).setValue(secName);
  sheet.getRange(newRow, COL.recClient ).setValue(clientName);
  sheet.getRange(newRow, COL.recStart  ).setValue(timeStr).setNumberFormat('@');
  sheet.getRange(newRow, COL.recMemo   ).setValue(memo || '');

  // 稼働時間の数式（終了後に自動計算）
  sheet.getRange(newRow, COL.recHours).setFormula(
    `=IF(AND(D${newRow}<>"",E${newRow}<>""),E${newRow}-D${newRow},"")`
  );

  // 書式：日付・時刻列
  sheet.getRange(newRow, COL.recDate).setNumberFormat('yyyy/MM/dd');
  sheet.getRange(newRow, COL.recHours).setNumberFormat('[h]:mm');

  return { ok: true, startTime: timeStr, autoEnded: current ? current.client : null };
}

/** 稼働終了 */
function endWork(clientName, memo, note) {
  const email = Session.getActiveUser().getEmail();
  const secName = _getSecName(email);
  if (!secName) return { ok: false, msg: '担当マスターにメールアドレスが登録されていません。' };

  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheet = ss.getSheetByName(SHEET.record);
  const now = new Date();
  const jst = _toJST(now);

  const current = getCurrentWorking();
  if (!current || current.client !== clientName) {
    return { ok: false, msg: `${clientName} の稼働記録が見つかりません。` };
  }

  _setEndTime(sheet, current.rowIndex, jst);
  if (memo) {
    sheet.getRange(current.rowIndex, COL.recMemo).setValue(memo);
  }
  if (note) {
    sheet.getRange(current.rowIndex, COL.recNote).setValue(note);
  }

  const timeStr = Utilities.formatDate(jst, 'Asia/Tokyo', 'HH:mm');
  return { ok: true, endTime: timeStr };
}

/** 未終了レコード一覧を返す（ログインユーザーの全未終了記録） */
function getOpenRecords() {
  const email = Session.getActiveUser().getEmail();
  const secName = _getSecName(email);
  if (!secName) return [];

  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheet = ss.getSheetByName(SHEET.record);
  const lastRow = sheet.getLastRow();
  if (lastRow < DATA_START) return [];

  const data = sheet.getRange(DATA_START, 1, lastRow - DATA_START + 1, COL.recNote).getValues();
  const result = [];
  for (let i = 0; i < data.length; i++) {
    const rowSec   = String(data[i][COL.recSecName - 1]).trim();
    const rowStart = data[i][COL.recStart - 1];
    const rowEnd   = data[i][COL.recEnd - 1];
    if (rowSec === secName && rowStart !== '' && rowEnd === '') {
      const rawDate = data[i][COL.recDate - 1];
      result.push({
        rowIndex : DATA_START + i,
        date     : rawDate instanceof Date
                     ? Utilities.formatDate(rawDate, 'Asia/Tokyo', 'yyyy/MM/dd')
                     : String(rawDate).trim(),
        client   : String(data[i][COL.recClient - 1]).trim(),
        startTime: _formatTime(rowStart),
      });
    }
  }
  return result;
}

/** 稼働記録を手動修正（終了時刻セット＋修正フラグ記録） */
function correctRecord(rowIndex, endTime) {
  const email = Session.getActiveUser().getEmail();
  const secName = _getSecName(email);
  if (!secName) return { ok: false, msg: '担当マスターにメールアドレスが登録されていません。' };

  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheet = ss.getSheetByName(SHEET.record);

  // 自分のレコードか確認
  const rowSec = String(sheet.getRange(rowIndex, COL.recSecName).getValue()).trim();
  if (rowSec !== secName) return { ok: false, msg: '自分の稼働記録のみ修正できます。' };

  // 形式チェック（HH:mm）
  if (!/^\d{1,2}:\d{2}$/.test(endTime)) return { ok: false, msg: '終了時刻の形式が正しくありません（HH:mm）。' };

  sheet.getRange(rowIndex, COL.recEnd).setValue(endTime).setNumberFormat('@');
  sheet.getRange(rowIndex, COL.recFlag).setValue('手動修正');

  return { ok: true };
}

// ============================================================
// カスタムメニュー
// ============================================================

function onOpen() {
  SpreadsheetApp.getUi()
    .createMenu('⚙️ 管理メニュー')
    .addItem('サマリーを更新', 'updateSummaries')
    .addItem('稼働記録に書式を適用', 'formatRecordSheet')
    .addToUi();
}

/** 秘書別・クライアント別サマリーを更新（GASで動的生成） */
function updateSummaries() {
  _updateSecSummary();
  _updateCliSummary();
  SpreadsheetApp.getUi().alert('サマリーを更新しました。');
}

function _updateSecSummary() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const recSheet = ss.getSheetByName(SHEET.record);
  const sumSheet = ss.getSheetByName(SHEET.secSum);

  // 対象年月をB3から取得（空なら全期間）
  const targetMonth = sumSheet.getRange('B3').getValue();

  const records = _getRecords(recSheet);
  const filtered = targetMonth
    ? records.filter(r => _isSameMonth(r.date, targetMonth))
    : records;

  // 秘書×クライアントで集計
  const map = {};
  filtered.forEach(r => {
    if (!r.hours) return;
    const key = r.secName + '__' + r.client;
    if (!map[key]) map[key] = { secName: r.secName, client: r.client, totalMs: 0, days: new Set() };
    map[key].totalMs += r.hours;
    map[key].days.add(r.date);
  });

  const rows = Object.values(map).sort((a,b) => a.secName.localeCompare(b.secName, 'ja'));

  // サマリー書き込み（6行目から）
  const startRow = 6;
  const headerRow = 5;
  const detailCol = 7; // G列から詳細テーブル
  const lastRow = Math.max(sumSheet.getLastRow(), headerRow);

  // サマリー列クリア
  if (lastRow >= startRow) {
    sumSheet.getRange(startRow, 1, lastRow - startRow + 1, 5).clearContent();
  }
  if (rows.length > 0) {
    const out = rows.map(r => [
      r.secName,
      r.client,
      _msToHHMM(r.totalMs),
      r.days.size,
      ''
    ]);
    sumSheet.getRange(startRow, 1, out.length, 5).setValues(out);
  }

  // 詳細テーブル（右側）クリア＆書き込み
  sumSheet.getRange(headerRow, detailCol, lastRow - headerRow + 1, 8).clearContent();
  sumSheet.getRange(headerRow, detailCol, 1, 8).setValues([[
    '日付', '秘書名', 'クライアント名', '開始', '終了', '稼働時間', '作業内容', '備考'
  ]]);
  if (filtered.length > 0) {
    const detail = filtered
      .sort((a, b) => a.date.localeCompare(b.date))
      .map(r => [
        r.date,
        r.secName,
        r.client,
        r.start || '',
        r.end || '',
        r.hours ? _msToHHMM(r.hours) : '',
        r.memo || '',
        r.note || '',
      ]);
    sumSheet.getRange(startRow, detailCol, detail.length, 8).setValues(detail);
  }
}

function _updateCliSummary() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const recSheet = ss.getSheetByName(SHEET.record);
  const sumSheet = ss.getSheetByName(SHEET.cliSum);

  const targetMonth = sumSheet.getRange('B3').getValue();
  const records = _getRecords(recSheet);
  const filtered = targetMonth
    ? records.filter(r => _isSameMonth(r.date, targetMonth))
    : records;

  const map = {};
  filtered.forEach(r => {
    if (!r.hours) return;
    const key = r.client + '__' + r.secName;
    if (!map[key]) map[key] = { client: r.client, secName: r.secName, totalMs: 0, days: new Set() };
    map[key].totalMs += r.hours;
    map[key].days.add(r.date);
  });

  const rows = Object.values(map).sort((a,b) => a.client.localeCompare(b.client, 'ja'));

  const startRow = 6;
  const headerRow = 5;
  const detailCol = 7; // G列から詳細テーブル
  const lastRow = Math.max(sumSheet.getLastRow(), headerRow);

  // サマリー列クリア
  if (lastRow >= startRow) {
    sumSheet.getRange(startRow, 1, lastRow - startRow + 1, 5).clearContent();
  }
  if (rows.length > 0) {
    const out = rows.map(r => [
      r.client,
      r.secName,
      _msToHHMM(r.totalMs),
      r.days.size,
      ''
    ]);
    sumSheet.getRange(startRow, 1, out.length, 5).setValues(out);
  }

  // 詳細テーブル（右側）クリア＆書き込み
  sumSheet.getRange(headerRow, detailCol, lastRow - headerRow + 1, 8).clearContent();
  sumSheet.getRange(headerRow, detailCol, 1, 8).setValues([[
    '日付', 'クライアント名', '秘書名', '開始', '終了', '稼働時間', '作業内容', '備考'
  ]]);
  if (filtered.length > 0) {
    const detail = filtered
      .sort((a, b) => a.date.localeCompare(b.date))
      .map(r => [
        r.date,
        r.client,
        r.secName,
        r.start || '',
        r.end || '',
        r.hours ? _msToHHMM(r.hours) : '',
        r.memo || '',
        r.note || '',
      ]);
    sumSheet.getRange(startRow, detailCol, detail.length, 8).setValues(detail);
  }
}

/** 稼働記録シートの書式を整える */
function formatRecordSheet() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheet = ss.getSheetByName(SHEET.record);
  const lastRow = sheet.getLastRow();
  if (lastRow < DATA_START) return;

  sheet.getRange(DATA_START, COL.recDate, lastRow - DATA_START + 1, 1)
    .setNumberFormat('yyyy/MM/dd');
  sheet.getRange(DATA_START, COL.recHours, lastRow - DATA_START + 1, 1)
    .setNumberFormat('[h]:mm');
}

// ============================================================
// 内部ヘルパー
// ============================================================

function _getSecName(email) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheet = ss.getSheetByName(SHEET.master);
  const rows = sheet.getDataRange().getValues();
  for (let i = HEADER_ROW; i < rows.length; i++) {
    if (String(rows[i][COL.masterEmail - 1]).trim() === email) {
      return String(rows[i][COL.masterSecName - 1]).trim();
    }
  }
  return null;
}

function _setEndTime(sheet, rowIndex, jst) {
  const timeStr = Utilities.formatDate(jst, 'Asia/Tokyo', 'HH:mm');
  sheet.getRange(rowIndex, COL.recEnd).setValue(timeStr).setNumberFormat('@');
}

function _toJST(date) {
  return new Date(date.toLocaleString('ja-JP', { timeZone: 'Asia/Tokyo' }));
}

function _formatTime(val) {
  if (!val) return '';
  if (val instanceof Date) return Utilities.formatDate(val, 'Asia/Tokyo', 'HH:mm');
  return String(val);
}

function _getRecords(sheet) {
  const lastRow = sheet.getLastRow();
  if (lastRow < DATA_START) return [];
  const data = sheet.getRange(DATA_START, 1, lastRow - DATA_START + 1, COL.recNote).getValues();
  return data.map((r, i) => ({
    rowIndex : DATA_START + i,
    date     : r[COL.recDate - 1] instanceof Date
                 ? Utilities.formatDate(r[COL.recDate - 1], 'Asia/Tokyo', 'yyyy/MM/dd')
                 : String(r[COL.recDate - 1]).trim(),
    secName  : String(r[COL.recSecName - 1]).trim(),
    client   : String(r[COL.recClient - 1]).trim(),
    start    : r[COL.recStart - 1],
    end      : r[COL.recEnd - 1],
    hours    : _parseHours(r[COL.recHours - 1]),
    memo     : r[COL.recMemo - 1],
    note     : r[COL.recNote - 1],
  })).filter(r => r.secName !== '');
}

function _parseHours(val) {
  if (!val) return 0;
  if (typeof val === 'number') return val * 24 * 3600 * 1000; // シリアル値→ms
  if (val instanceof Date) {
    return (val.getHours() * 3600 + val.getMinutes() * 60) * 1000;
  }
  return 0;
}

function _msToHHMM(ms) {
  const totalMin = Math.floor(ms / 60000);
  const h = Math.floor(totalMin / 60);
  const m = totalMin % 60;
  return `${h}:${String(m).padStart(2,'0')}`;
}

function _isSameMonth(dateStr, target) {
  if (!dateStr || !target) return false;
  const d = new Date(dateStr);
  const t = new Date(target);
  return d.getFullYear() === t.getFullYear() && d.getMonth() === t.getMonth();
}
